async def execute_secondary_groups(
    function: str | collections.abc.Callable[..., str],
    *positional_args: object,
    args: list[typing.Any] | None = None,
    other: str | collections.abc.Callable[..., str],
    other_args: object | list[typing.Any] | None = None,
    signal: str | collections.abc.Callable[..., str],
    signal_args: object | list[typing.Any] | None = None,
) -> temporalio.workflow.NexusOperationHandle[ExecuteFunctionResult,]:
    """
    Args:
        positional_args: Positional arguments for function. Cannot be set if args is
            set.
        args: List-form arguments for function. Cannot be set if positional_args are
            set. For typed function callables, list contents are not statically
            typechecked; pass function arguments positionally for precise typechecking.
        other_args: Argument value, or list of argument values, for other. For typed
            single-argument signals, scalar signal_args values are statically
            typechecked. List-form signal_args values are not precisely typechecked. To
            pass a single signal argument that is itself a list, wrap it in another
            list; otherwise the list is interpreted as multiple signal arguments.
        signal_args: Argument value, or list of argument values, for signal. For typed
            single-argument signals, scalar signal_args values are statically
            typechecked. List-form signal_args values are not precisely typechecked. To
            pass a single signal argument that is itself a list, wrap it in another
            list; otherwise the list is interpreted as multiple signal arguments.
    """
    if positional_args and args is not None:
        raise TypeError("cannot specify both positional arguments and args")
    normalized_args: list[typing.Any] | None = (
        list(positional_args) if positional_args else args
    )
    normalized_other_args: list[typing.Any] | None
    if other_args is None:
        normalized_other_args = None
    elif isinstance(other_args, list):
        normalized_other_args = typing.cast(list[typing.Any], other_args)
    else:
        normalized_other_args = [other_args]
    normalized_signal_args: list[typing.Any] | None
    if signal_args is None:
        normalized_signal_args = None
    elif isinstance(signal_args, list):
        normalized_signal_args = typing.cast(list[typing.Any], signal_args)
    else:
        normalized_signal_args = [signal_args]
    request = ExecuteSecondaryGroupsRequest(
        function=function,
        args=normalized_args,
        other=other,
        other_args=normalized_other_args,
        signal=signal,
        signal_args=normalized_signal_args,
    )
    return await _execute_secondary_groups(request)
